import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export interface Candidate {
    id: string;
    name: string;
    rating: number;
    exp: string;
    verified: boolean;
    bid: string;
    excerpt: string;
    init: string;
    color: string;
    status: 'pending' | 'accepted' | 'rejected' | 'completed';
}

export interface Job {
    id: string;
    title: string;
    location: string;
    city: string;
    wage: string;
    daily_rate: number;
    category: string;
    description: string;
    skills_required: string[];
    status: 'active' | 'closed';
    posted: string;
    applicants: number;
    filled: number;
    total: number;
    employer_id: string;
    employer_name: string;
    employer_verified: boolean;
    is_urgent: boolean;
    duration: string;
    perks: string[];
    candidates: Candidate[];
}

export interface HistoryRecord {
    id: string;
    workerName: string;
    workerInit: string;
    workerColor: string;
    workerRating: number;
    workerExp: string;
    jobTitle: string;
    jobLocation: string;
    wage: string;
    hiredDate: string;
    completedDate: string;
    status: 'completed';
}

interface AppDataState {
    jobs: Job[];
    history: HistoryRecord[];
    loading: boolean;
    setJobs: (jobs: Job[]) => void;
    setHistory: (history: HistoryRecord[]) => void;
    setLoading: (loading: boolean) => void;
    updateCandidateStatus: (jobId: string, candidateName: string, status: 'accepted' | 'rejected') => void;
    markWorkCompleted: (jobId: string, candidateName: string) => void;
    addJob: (job: Job) => void;
    addCandidate: (jobId: string, candidate: Candidate) => void;
}

export const useAppDataStore = create<AppDataState>()(
    persist(
        (set, get) => ({
            jobs: [],
            history: [],
            loading: false,

            setJobs: (jobs) => set({ jobs }),
            setHistory: (history) => set({ history }),
            setLoading: (loading) => set({ loading }),
            addJob: (job) => set({ jobs: [...get().jobs, job] }),

            addCandidate: (jobId, candidate) => {
                const jobs = get().jobs.map((j) => {
                    if (j.id !== jobId) return j;
                    // Prevent duplicate applications for the same candidate ID
                    if (j.candidates.some(c => c.id === candidate.id)) return j;
                    return {
                        ...j,
                        candidates: [...j.candidates, candidate],
                        applicants: j.applicants + 1,
                    };
                });
                set({ jobs });
            },

            updateCandidateStatus: (jobId, candidateName, status) => {
                const jobs = get().jobs.map((j) => {
                    if (j.id !== jobId) return j;

                    let filledChange = 0;
                    const updatedCandidates = j.candidates.map((c) => {
                        if (c.name === candidateName) {
                            // If we are hiring someone who wasn't hired yet
                            if (status === 'accepted' && c.status !== 'accepted') filledChange = 1;
                            // If we are un-hiring (rejecting someone previously accepted)
                            if (status === 'rejected' && c.status === 'accepted') filledChange = -1;
                            return { ...c, status };
                        }
                        return c;
                    });

                    return {
                        ...j,
                        candidates: updatedCandidates,
                        filled: Math.min(j.total, Math.max(0, j.filled + filledChange))
                    };
                });
                set({ jobs });
            },

            markWorkCompleted: (jobId, candidateName) => {
                const jobs = get().jobs.map((j) => {
                    if (j.id !== jobId) return j;
                    return {
                        ...j,
                        candidates: j.candidates.map((c) =>
                            c.name === candidateName ? { ...c, status: 'completed' as const } : c
                        ),
                        status: 'closed' as const // Close job when work is completed
                    };
                });
                set({ jobs });
            },
        }),
        {
            name: 'shramsetu-app-data-v1',
        }
    )
);
